<template>
  <view class="post-detail">
    <!-- 头部返回 -->
    <view class="header">
      <text class="back-btn" @click="goBack">← 返回</text>
    </view>

    <!-- 帖子主体 -->
    <view class="post-container">
      <!-- 发帖人信息 -->
      <view class="post-author">
        <image :src="author.avatar" class="author-avatar" mode="cover"></image>
        <view class="author-info">
          <text class="author-name">{{ author.name }}</text>
          <text class="author-desc">{{ author.desc }}</text>
          <text class="post-time">{{ author.time }}</text>
        </view>
      </view>

      <!-- 帖子内容 -->
      <view class="post-content">
        <text class="content-text">{{ content.text }}</text>
        <text class="expand-btn" v-if="content.isExpandable" @click="toggleExpand">展开↓</text>
      </view>

      <!-- 互动栏 -->
      <view class="interaction-bar">
        <view class="interaction-item" @click="handleComment">
          <text class="iconfont"></text>
          <text class="count">{{ interaction.comment }}</text>
        </view>
        <view class="interaction-item" @click="handleLike">
          <!-- 已修复：使用数组语法的:class，避免重复属性 -->
          <text :class="['iconfont', { 'active': isLiked }]"></text>
          <text class="count">{{ interaction.like }}</text>
        </view>
      </view>

      <!-- 评论列表 -->
      <view class="comment-list">
        <!-- 一级评论 -->
        <view class="comment-item" v-for="(comment, index) in comments" :key="index">
          <image :src="comment.avatar" class="comment-avatar" mode="cover"></image>
          <view class="comment-info">
            <text class="comment-name">{{ comment.name }}</text>
            <text class="comment-content">{{ comment.content }}</text>
            <view class="comment-meta">
              <text class="comment-time">{{ comment.time }}</text>
              <!-- 回复按钮：点击时标记目标评论，不改变输入框位置 -->
              <text class="reply-btn" @click="setReplyTarget(index)">回复</text>
            </view>

            <!-- 嵌套的回复列表：用户回复内容显示在这里 -->
            <view class="reply-list" v-if="comment.replies && comment.replies.length > 0">
              <view class="reply-item" v-for="(reply, replyIdx) in comment.replies" :key="replyIdx">
                <image :src="reply.avatar" class="reply-avatar" mode="cover"></image>
                <view class="reply-info">
                  <text class="reply-name">{{ reply.name }}</text>
                  <text class="reply-content">
                    <text class="reply-at">@{{ reply.atName }}：</text>{{ reply.content }}
                  </text>
                  <text class="reply-time">{{ reply.time }}</text>
                </view>
              </view>
            </view>
          </view>
        </view>
      </view>

      <!-- 底部评论输入框：固定不变，同时支持一级评论和回复 -->
      <view class="comment-input">
        <!-- 输入框提示文字随回复状态变化 -->
        <input 
          type="text" 
          :placeholder="replyTargetIndex === -1 ? '留下你的评论吧' : `回复 @${getTargetCommentName()}`" 
          v-model="inputValue" 
          class="input-field" 
        />
        <button class="send-btn" @click="sendContent">↑</button>
      </view>
    </view>
  </view>
</template>

<script>
export default {
  data() {
    return {
      isLiked: false, // 是否点赞
      inputValue: '', // 评论/回复输入内容
      replyTargetIndex: -1, // 回复目标评论索引（-1=发布一级评论，>=0=回复对应评论）
      author: {
        avatar: '/static/icon/社交媒体1.png',
        name: '温特斯',
        desc: '迪拜12年资深房地产专家……',
        time: '1分钟前'
      },
      content: {
        text: 'AI时代，最重要的不是资源、规模或起点，而是斜率——你进步的速度。范式变了，成本重构了，唯有斜率能拉开差距，其他都不重要……',
        isExpandable: true // 是否可展开
      },
      interaction: {
        comment: 4,
        like: 6
      },
      comments: [
        {
          avatar: '/static/icon/社交媒体2.png',
          name: '梨鸠晒普',
          content: '6666',
          time: '15:08',
          replies: [] // 存储当前评论的所有回复
        },
        {
          avatar: '/static/icon/社交媒体2.png',
          name: '梨鸠晒普',
          content: '翻工最紧要系要打风',
          time: '15:06',
          replies: [] // 存储当前评论的所有回复
        },
        {
          avatar: '/static/icon/社交媒体2.png',
          name: '梨鸠晒普',
          content: '翻工最紧要系要打风',
          time: '15:06',
          replies: [] // 存储当前评论的所有回复
        }
      ]
    }
  },
  methods: {
    goBack() {
      uni.navigateBack();
    },
    toggleExpand() {
      this.content.isExpandable = false;
      uni.showToast({ title: '内容已展开', icon: 'none' });
    },
    handleLike() {
      this.isLiked = !this.isLiked;
      this.interaction.like = this.isLiked ? this.interaction.like + 1 : this.interaction.like - 1;
      uni.showToast({ title: this.isLiked ? '点赞成功' : '取消点赞', icon: 'none' });
    },
    handleComment() {
      // 点击评论按钮：切换到一级评论模式，聚焦输入框
      this.replyTargetIndex = -1;
      this.$nextTick(() => {
        uni.createSelectorQuery().select('.input-field').fields({ focus: true }, () => {}).exec();
      });
    },
    setReplyTarget(index) {
      // 点击回复按钮：仅标记目标评论，不改变输入框位置，聚焦输入框
      this.replyTargetIndex = index;
      this.inputValue = ''; // 清空历史输入
      this.$nextTick(() => {
        uni.createSelectorQuery().select('.input-field').fields({ focus: true }, () => {}).exec();
      });
    },
    getTargetCommentName() {
      // 获取目标评论的用户名（用于输入框提示）
      if (this.replyTargetIndex === -1 || !this.comments[this.replyTargetIndex]) {
        return '';
      }
      return this.comments[this.replyTargetIndex].name;
    },
    sendContent() {
      // 统一发送逻辑：根据回复目标索引判断是发布一级评论还是嵌套回复
      const content = this.inputValue.trim();
      if (!content) {
        uni.showToast({ title: '请输入内容', icon: 'none' });
        return;
      }

      const currentTime = new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
      const userInfo = {
        avatar: '/static/icon/我的.png', // 当前用户头像
        name: '我' // 当前用户名
      };

      // 1. 回复评论：将内容嵌套到目标评论的replies数组中
      if (this.replyTargetIndex >= 0) {
        const targetComment = this.comments[this.replyTargetIndex];
        targetComment.replies.push({
          ...userInfo,
          atName: targetComment.name, // 被回复人的名字
          content: content,
          time: currentTime
        });
        uni.showToast({ title: '回复发送成功', icon: 'success' });
      } 
      // 2. 发布一级评论：添加到comments数组
      else {
        this.comments.unshift({
          ...userInfo,
          content: content,
          time: currentTime,
          replies: [] // 初始化回复数组
        });
        uni.showToast({ title: '评论发送成功', icon: 'success' });
      }

      // 发送后重置状态
      this.interaction.comment += 1;
      this.inputValue = '';
      this.replyTargetIndex = -1; // 重置为一级评论模式
    }
  }
}
</script>

